UPDATE companies SET description='CB Solar Inc. was founded in 2014 in Des Moines, Iowa, as a turnkey solar contractor serving residential, agricultural, and commercial clients across the state. CB Solar serves three primary markets: residential homeowners, agricultural operations, and commercial businesses. In agriculture, the company has developed expertise in integrating solar with livestock and grain facilities, citing installations for swine, beef, poultry, and grain-handling operations. The company distinguishes itself as the first in Iowa to specialize in agricultural solar integration. It has been recognized on Solar Power World''s Top Solar Contractors list every year since 2014, a distinction it highlights as evidence of consistent performance.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Solar system design", "Solar installation", "Turnkey project management", "Agricultural solar integration"], "industries": ["Residential solar", "Agricultural solar", "Commercial solar", "Swine farming", "Beef farming", "Poultry farming", "Grain handling"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": [], "facts_used": ["Founded in 2014 -> db", "Headquartered in Des Moines, Iowa -> db", "Turnkey solar contractor offering design and installation -> /", "First Iowa company to specialize in agricultural solar integration -> /", "Listed as Top Solar Contractor by Solar Power World every year since 2014 -> /", "Serves residential, agricultural, and commercial customers -> /", "Agricultural installations for swine, beef, poultry, and grain handling -> /"], "company_type": "Installer / service company", "makes_products": "no", "type_evidence": "We are a turnkey contractor and can design and install systems sized for any customer.", "founded_year": "2014", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=