, "Offers guide for building river epoxy tables -> /", "Featured in a book -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "We specialize in custom epoxy river tables, residential and commercial bar creation, and epoxy interior decor.", "founded_year": "2019", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='cf-woodworks' AND approved AND profile IS NULL;
